    "content": "st = []\n\n#Stack implement using List\n# Append\n# st.append(8)\n# st.append(4)\n# st.append(3)\n# st.append(10)\n# st.append(2)\n\nprint(st)\n\n# Popping\n# st.pop()\n\n# print(st)\n# print(st[-1])\n\n\n#Using OOP:\nclass Stack:\n    def __init__(self):\n        self.st = []\n\n    def push(self, x):\n        self.st.append(x)\n\n    def pop(self):\n        if len(self.st) == 0:\n            return -1\n        return self.st.pop()\n\n    def top(self):\n        if len(self.st) == 0:\n            return -1\n        return self.st[-1]\n\n    def size(self):\n        return len(self.st)\n\n\nstack = Stack()\n\nstack.push(8)\nstack.push(9)\nstack.push(5)\nstack.push(7)\nstack.push(4)\nstack.push(3)\n\nprint(\"Printing Top most element\",stack.top())  # 3\nprint(\"Element popped\",stack.pop())  # 3\nprint(\"Printing Top most element\",stack.top())  # 4\nprint(\"Element popped\",stack.size()) # 5\n\n\n#Stack implementation using Linked List:\nclass Node:\n    def __init__(Self, data):\n        self.data = data\n        self.next = None\n\n"
