    "type": "py",
    "content": "#!/usr/bin/env python3\n\"\"\"Build the website's complete notes library from repository Markdown and PDFs.\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport re\nimport subprocess\nfrom pathlib import Path\n\n\nROOT = Path(__file__).resolve().parents[1]\nDOCS_DIR = ROOT / \"DataStructures_Documentation\"\nPDF_DIR = ROOT / \"Python_Course\"\nOUTPUT = ROOT / \"website\" / \"assets\" / \"js\" / \"content-library-data.js\"\n\n\ndef title_from_markdown(text: str, fallback: str) -> str:\n    match = re.search(r\"^#\\s+(.+)$\", text, re.MULTILINE)\n    return match.group(1).strip() if match else fallback\n\n\ndef clean_pdf_text(text: str) -> str:\n    lines = [line.rstrip() for line in text.replace(\"\\x00\", \"\").splitlines()]\n    cleaned: list[str] = []\n    blank = False\n    for line in lines:\n        if not line.strip():\n            if not blank:\n                cleaned.append(\"\")\n            blank = True\n            continue\n        blank = False\n        cleaned.append(line)\n    return \"\\n\".join(cleaned).strip()\n\n\ndef category_for(path: Path) -> str:\n    name = path.stem.lower()\n    if any(word in name for word in (\"sort\", \"search\", \"complexity\", \"adaptive\", \"stable\")):\n        return \"Algorithms\"\n    if any(word in name for word in (\"numpy\", \"pandas\")):\n        return \"Data Science\"\n    if \"oop\" in name:\n        return \"OOP\"\n    if \"index\" in name or \"readme\" in name:\n        return \"Index\"\n    return \"Data Structures\"\n\n\nitems: list[dict[str, object]] = []\n\nfor path in sorted(DOCS_DIR.rglob(\"*.md\")):\n    text = path.read_text(encoding=\"utf-8\")\n    rel = path.relative_to(ROOT).as_posix()\n    items.append(\n        {\n            \"id\": \"md-\" + re.sub(r\"[^a-z0-9]+\", \"-\", rel.lower()).strip(\"-\"),\n            \"title\": title_from_markdown(text, path.stem.replace(\"_\", \" \")),\n            \"source\": \"Markdown\",\n            \"category\": category_for(path),\n            \"path\": rel,\n            \"content\": text,\n            \"lines\": len(text.splitlines()),\n        }\n    )\n\nfor path in sorted(PDF_DIR.glob(\"*.pdf\")):\n    result = subprocess.run(\n        [\"pdftotext\", \"-layout\", str(path), \"-\"],\n        check=True,\n        capture_output=True,\n        text=True,\n        encoding=\"utf-8\",\n        errors=\"replace\",\n    )\n    pages = [clean_pdf_text(page) for page in result.stdout.split(\"\\f\") if page.strip()]\n    title = path.stem.replace(\"_\", \" \")\n    if path.name == \"OOPs_Notes.md.pdf\":\n        title = \"Complete OOPs Notes: Beginner to Interview-Ready\"\n    items.append(\n        {\n            \"id\": \"pdf-\" + re.sub(r\"[^a-z0-9]+\", \"-\", path.stem.lower()).strip(\"-\"),\n            \"title\": title,\n            \"source\": \"PDF\",\n            \"category\": \"OOP\" if \"oop\" in path.name.lower() else \"Course Lectures\",\n            \"path\": path.relative_to(ROOT).as_posix(),\n            \"content\": \"\\n\\n\".join(pages),\n            \"pages\": pages,\n            \"lines\": sum(len(page.splitlines()) for page in pages),\n        }\n    )\n\npayload = json.dumps(items, ensure_ascii=False, separators=(\",\", \":\"))\nOUTPUT.write_text(\n    \"// Generated by tools/build_content_library.py. Do not edit manually.\\n\"\n    f\"const CONTENT_LIBRARY = {payload};\\n\",\n    encoding=\"utf-8\",\n)\nprint(f\"Generated {OUTPUT.relative_to(ROOT)} with {len(items)} complete documents.\")\n"
